window.__finlexDocLoaded(10172,{"id":10172,"articles":[{"id":1000719,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Requires public entities to report operating segment information through the eyes of the Chief Operating Decision Maker (CODM), significantly expanded by ASU 2023-07 to mandate disclosure of significant segment expenses.","seq":0},{"id":1000720,"no":"ASC 280-10","heading":"CODM Approach & ASU 2023-07 Significant Segment Expenses","text":"• Identification & Aggregation (ASC 280-10-50-1 to 50-12): Operating segments identified via CODM review; quantitative 10% revenue/profit/asset thresholds and 75% consolidated external revenue coverage test.\n• Significant Segment Expenses (ASU 2023-07, effective FY2024+): Must disclose significant segment expense categories regularly provided to the CODM and included in segment profit/loss, plus the title/position of the CODM and single-reportable-segment entity disclosures.\n• Multiple Profit Measures: ASU 2023-07 permits disclosing additional CODM profit measures alongside the measure most consistent with GAAP.","seq":1},{"id":1000721,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Converged with IFRS 8 on the CODM management approach, though ASU 2023-07's mandatory significant segment expense table goes beyond current IFRS 8 requirements; matrix organizations use products/services under ASC 280-10-50-9.","seq":2},{"id":1000722,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
